#'     \item{pkg_cppflags, pkg_cxxflags, pkg_libs}{The package-level \code{PKG_CPPFLAGS}/
#'       \code{PKG_CXXFLAGS}/\code{PKG_LIBS} used when compiling/linking EDI's C++
#'       sources.}
#'     \item{compiler}{The compiler identification string (\code{__VERSION__}).}
#'     \item{compiler_optimize_macro}{Logical; \code{TRUE} iff the compiler defined
#'       \code{__OPTIMIZE__} (i.e. optimizations were enabled) when this translation
#'       unit was compiled.}
#'     \item{compiler_fast_math_macro}{Logical; \code{TRUE} iff \code{__FAST_MATH__}
