#'   (unweighted) variance-augmented variant.
#' @export
#' @keywords internal
fast_identity_binomial_regression_weighted_cpp <- function(X, y_r, weights_r, maxit = 100L, tol = 1e-6, fixed_idx = NULL, fixed_values = NULL, warm_start_beta = NULL, smart_cold_start = TRUE, warm_start_weights = NULL, warm_start_fisher_info = NULL, estimate_only = FALSE) {
